//! Marfim brain (P4): lossless differential port of the Node intelligence
//! oracle (`src/intel` + `src/intel/brain`), one module file per oracle
//! module, byte-exact for ints/strings and <=1 ulp for floats (exact
//! where the oracle math is elementary). Every module is validated by
//! committed JSONL fixtures generated by RUNNING the oracle under node —
//! the tests replay inputs and compare outputs; nothing is ported from
//! memory or docs.
//!
//! Determinism doctrine (INV): same input order, seeded RNG only, no
//! wall-clock, no HashMap iteration order in output-affecting paths.
//! Sealed eval sets are NEVER used for tuning.

#![forbid(unsafe_code)]
#![allow(clippy::module_inception)]

pub mod brain;
pub mod faculty;
pub mod intel;
pub mod util;

/// Reference to the oracle snapshot these modules were ported from.
pub const ORACLE: &str = "Node marfim archive/node-v1.2.0 (src/intel)";
